import { chromium } from "playwright";
import { readFileSync, writeFileSync } from "node:fs";

async function run() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Capture console errors
  const consoleErrors = [];
  page.on("pageerror", (err) => {
    console.error("Browser page error:", err);
    consoleErrors.push(err);
  });
  page.on("console", (msg) => {
    if (msg.type() === "error") {
      console.error("Browser console error:", msg.text());
      consoleErrors.push(msg.text());
    }
  });

  console.log("Navigating to http://localhost:3000/...");
  await page.goto("http://localhost:3000/");

  // Verify initial state
  const statusBefore = await page.locator("#status").textContent();
  const countBefore = await page.locator("#count").textContent();
  const errorsBefore = await page.locator("#errors").textContent();
  const eventsCountBefore = await page.locator("#events li").count();

  console.log("Initial state:", { statusBefore, countBefore, errorsBefore, eventsCountBefore });

  if (statusBefore !== "idle" || countBefore !== "0" || errorsBefore !== "0" || eventsCountBefore !== 0) {
    throw new Error("Initial state is incorrect!");
  }

  console.log("Clicking #start...");
  await page.locator("#start").click();

  // Wait a bit and check incremental rendering
  await page.waitForTimeout(1000);
  const statusDuring = await page.locator("#status").textContent();
  const countDuring = parseInt(await page.locator("#count").textContent() || "0", 10);
  const errorsDuring = parseInt(await page.locator("#errors").textContent() || "0", 10);
  const eventsCountDuring = await page.locator("#events li").count();

  console.log("State during streaming (at 1s):", { statusDuring, countDuring, errorsDuring, eventsCountDuring });

  if (statusDuring !== "streaming") {
    throw new Error("Status should be 'streaming' during streaming!");
  }
  if (eventsCountDuring === 0 || eventsCountDuring === 8) {
    throw new Error(`Events should render incrementally! Found ${eventsCountDuring} events at 1s.`);
  }

  // Wait for streaming to complete
  console.log("Waiting for status to be 'done'...");
  await page.waitForFunction(() => document.querySelector("#status")?.textContent === "done", { timeout: 10000 });

  const statusAfter = await page.locator("#status").textContent();
  const countAfter = await page.locator("#count").textContent();
  const errorsAfter = await page.locator("#errors").textContent();
  const eventsCountAfter = await page.locator("#events li").count();

  console.log("State after streaming:", { statusAfter, countAfter, errorsAfter, eventsCountAfter });

  if (statusAfter !== "done") {
    throw new Error("Status should be 'done' after completion!");
  }
  if (countAfter !== "8" || errorsAfter !== "2" || eventsCountAfter !== 8) {
    throw new Error("Final counts or event list items are incorrect!");
  }

  // Check event list item attributes and text
  const lis = page.locator("#events li");
  for (let i = 0; i < 8; i++) {
    const li = lis.nth(i);
    const dataIdx = await li.getAttribute("data-idx");
    const dataLevel = await li.getAttribute("data-level");
    const text = await li.textContent();
    console.log(`LI ${i}:`, { dataIdx, dataLevel, text });
    if (dataIdx !== String(i)) {
      throw new Error(`LI ${i} has incorrect data-idx: ${dataIdx}`);
    }
    if (!text.startsWith(`${dataLevel}: `)) {
      throw new Error(`LI ${i} text does not match level: ${text}`);
    }
  }

  // Now, edit data/events.log and start again to verify dynamic reading
  console.log("Editing data/events.log...");
  const originalLog = readFileSync("data/events.log", "utf-8");
  const modifiedLog = originalLog + "ERROR|A brand new error\n";
  writeFileSync("data/events.log", modifiedLog, "utf-8");

  try {
    console.log("Clicking #start again...");
    await page.locator("#start").click();

    // Wait for streaming to complete
    console.log("Waiting for status to be 'done' again...");
    await page.waitForFunction(() => document.querySelector("#status")?.textContent === "done", { timeout: 10000 });

    const countAfterEdit = await page.locator("#count").textContent();
    const errorsAfterEdit = await page.locator("#errors").textContent();
    const eventsCountAfterEdit = await page.locator("#events li").count();

    console.log("State after edit and streaming:", { countAfterEdit, errorsAfterEdit, eventsCountAfterEdit });

    if (countAfterEdit !== "9" || errorsAfterEdit !== "3" || eventsCountAfterEdit !== 9) {
      throw new Error("Dynamic reading of events.log failed!");
    }

    const lastLi = lis.nth(8);
    const lastDataIdx = await lastLi.getAttribute("data-idx");
    const lastDataLevel = await lastLi.getAttribute("data-level");
    const lastText = await lastLi.textContent();
    console.log("Last LI after edit:", { lastDataIdx, lastDataLevel, lastText });
    if (lastDataIdx !== "8" || lastDataLevel !== "ERROR" || lastText !== "ERROR: A brand new error") {
      throw new Error("Last LI has incorrect content/attributes!");
    }
  } finally {
    // Restore events.log
    writeFileSync("data/events.log", originalLog, "utf-8");
  }

  if (consoleErrors.length > 0) {
    throw new Error(`Found browser console errors: ${consoleErrors.join(", ")}`);
  }

  console.log("All tests passed successfully!");
  await browser.close();
}

run().catch((err) => {
  console.error("Test failed:", err);
  process.exit(1);
});

